import React, { useEffect, useRef, useState } from "react";
import { Html5Qrcode } from "html5-qrcode";
import axios from "axios";

function QRScanner() {

const scannerRef = useRef(null);
const [message,setMessage] = useState("");
const [user,setUser] = useState(null);

useEffect(()=>{

let scanner;

const startScanner = async () => {

try{

scanner = new Html5Qrcode("reader");
scannerRef.current = scanner;

const devices = await Html5Qrcode.getCameras();

if(devices.length === 0){
setMessage("No Camera Found");
return;
}

await scanner.start(
devices[0].id,
{
fps:10,
qrbox:{ width:250, height:250 }
},
(decodedText)=>{

console.log("QR SCANNED:",decodedText);

verifyUser(decodedText);

},
(error)=>{
// ignore scan errors
}
);

}catch(err){

console.log("Scanner error:",err);
setMessage("Camera Error");

}

};

setTimeout(startScanner,500);

return ()=>{

if(scannerRef.current){

scannerRef.current.stop()
.then(()=>scannerRef.current.clear())
.catch(()=>{});

}

};

},[]);


/* =========================
VERIFY USER
========================= */

const verifyUser = async(id)=>{

try{

const res = await axios.get(
`http://localhost:5000/verify-user/${id}`
);

if(res.data.success){

setUser(res.data.user);
setMessage("User Verified");

await axios.post(
"http://localhost:5000/mark-attendance",
{ user_id:id }
);

setMessage("Attendance Marked");

}else{

setUser(null);
setMessage("User Not Registered");

}

}catch(err){

console.log(err);
setMessage("Server Error");

}

};


return(

<div style={{padding:"20px"}}>

<h2>Admin QR Scanner</h2>

<div
id="reader"
style={{
width:"350px",
height:"350px",
border:"2px solid black"
}}
></div>

<h3>{message}</h3>

{user && (

<div>

<p>Name: {user.name}</p>
<p>College: {user.college_name}</p>
<p>Phone: {user.phone}</p>
<p>Event: {user.event_id}</p>

</div>

)}

</div>

);

}

export default QRScanner;
